import unittest
import mock
from mock import patch, call
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.pages.software import SoftwareUpdatePage, SoftwareUpdatePageViewPanel


class TestSoftwareUpdatePage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.software_update_page = SoftwareUpdatePage()

    def test_load_software_package_from_local_drive(self):
        file_path = "//path"
        timeout = 1
        expected_text = "success"
        self.software_update_page._view_panel.\
            load_software_package_from_local_drive = mock.Mock(return_value=expected_text)

        output = self.software_update_page.load_software_package_from_local_drive(file_path, timeout)
        self.software_update_page._view_panel. \
            load_software_package_from_local_drive.assert_called_once_with(file_path, timeout)
        self.assertEqual(output, expected_text)

    def test_load_software_package_from_remote_server(self):
        url = "https://something"
        sw_file = "aaa.zip"
        timeout = 1
        expected_text = "success"
        self.software_update_page._view_panel. \
            load_software_package_from_remote_server = mock.Mock(return_value=expected_text)

        output = self.software_update_page.load_software_package_from_remote_server(url, sw_file, timeout)
        self.software_update_page._view_panel. \
            load_software_package_from_remote_server.assert_called_once_with(url, sw_file, timeout)
        self.assertEqual(output, expected_text)

    def test_software_update(self):
        is_activate = True
        timeout = 1
        self.software_update_page._view_panel.software_update = mock.Mock()

        self.software_update_page.software_update(is_activate, timeout)
        self.software_update_page._view_panel.software_update.assert_called_once_with(is_activate, timeout)

    def test_cancel_software_update(self):
        self.software_update_page._view_panel.cancel_software_update = mock.Mock()

        self.software_update_page.cancel_software_update()
        self.software_update_page._view_panel.cancel_software_update.assert_called_once()

    def test_check_software_update_progress(self):
        expected_progress = "100%"
        self.software_update_page._view_panel.check_software_update_progress = mock.Mock(return_value=expected_progress)

        output = self.software_update_page.check_software_update_progress()
        self.software_update_page._view_panel.check_software_update_progress.assert_called_once()
        self.assertEqual(output, expected_progress)

    def test_check_current_software_version(self):
        return_dict = {'a': "1.0.0", 'b': '2.0.0'}
        key = 'a'
        expected_version = "1.0.0"
        self.software_update_page._view_panel.get_all_current_software_version = mock.Mock(return_value=return_dict)

        output = self.software_update_page.check_current_software_version(key)
        self.software_update_page._view_panel.get_all_current_software_version.assert_called_once()
        self.assertEqual(output, expected_version)

    def test_save_sw_update_report(self):
        expect_dir = '//dir'
        download_timeout = 1
        self.software_update_page._view_panel.save_sw_update_report = mock.Mock(return_value=expect_dir)

        output = self.software_update_page.save_sw_update_report(download_timeout)
        self.software_update_page._view_panel.save_sw_update_report.assert_called_once_with(download_timeout)
        self.assertEqual(output, expect_dir)

    def test_software_rollback(self):
        self.software_update_page._view_panel.software_rollback = mock.Mock()

        self.software_update_page.software_rollback()
        self.software_update_page._view_panel.software_rollback.assert_called_once()

    def test_backup_bts_site_configuration(self):
        expect_dir = '/dir'
        download_timeout = 1
        self.software_update_page._view_panel.backup_bts_site_configuration = mock.Mock(return_value=expect_dir)

        output = self.software_update_page.backup_bts_site_configuration(download_timeout)
        self.software_update_page._view_panel.backup_bts_site_configuration.assert_called_once_with(download_timeout)
        self.assertEqual(output, expect_dir)


class TestSoftwareUpdatePageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        self.webdriver = mock.MagicMock()
        mock_driver.return_value = self.webdriver
        self.page_view_panel = SoftwareUpdatePageViewPanel()

    def test_load_software_package_from_local_drive(self):
        file_path = "//path"
        timeout = 1
        expected_text = "software package load success"
        self.page_view_panel.select_radiobox_by_xpath = mock.Mock()
        self.page_view_panel.load_file_from_hidden_button = mock.Mock()
        self.page_view_panel.wait_for_visibility_by_xpath = mock.Mock()

        output = self.page_view_panel.load_software_package_from_local_drive(file_path, timeout)
        self.page_view_panel.select_radiobox_by_xpath.\
            assert_called_once_with(self.page_view_panel._LOCAL_DRIVE_RADIO_BOX_XPATH)
        self.page_view_panel.load_file_from_hidden_button.\
            assert_called_once_with(self.page_view_panel._LOCAL_LOAD_HIDDEN_BUTTON_SCRIPT,
                                    self.page_view_panel._LOCAL_LOAD_HIDDEN_BUTTON_XPATH, file_path, timeout)
        self.page_view_panel.wait_for_visibility_by_xpath.\
            assert_called_once_with(self.page_view_panel._LOAD_INFO_SUCCESS_XPATH, timeout)
        self.assertEqual(output, expected_text)

    def test_load_software_package_from_remote_server(self):
        url = "https://something"
        sw_file = "aaa.zip"
        timeout = 1
        self.page_view_panel.select_radiobox_by_xpath = mock.Mock()

        self.page_view_panel.load_software_package_from_remote_server(url, sw_file, timeout)
        self.page_view_panel.select_radiobox_by_xpath. \
            assert_called_once_with(self.page_view_panel._REMOTE_SERVER_RADIO_BOX_XPATH)
        # TODO case will be finished when source code done

    @patch('taf.ul.oam.selenium_coam.pages.software.WebElementManagerReloadModal')
    def test_software_update(self, mock_modal):
        is_activate = True
        timeout = 1
        self.page_view_panel.select_checkbox_by_specified_status = mock.Mock()
        self.page_view_panel.click_enabled_element_after_visible = mock.Mock()
        modal = mock_modal.return_value
        modal.wait_until_login_modal_appear = mock.Mock()
        modal.confirm = mock.Mock()

        self.page_view_panel.software_update(is_activate, timeout)
        self.page_view_panel.select_checkbox_by_specified_status.\
            assert_called_once_with(is_activate, self.page_view_panel._ACTIVATE_CHECKBOX_SELECTED_XPATH,
                                    self.page_view_panel._ACTIVATE_CHECKBOX_XPATH)
        self.page_view_panel.click_enabled_element_after_visible.\
            assert_called_once_with((By.XPATH, self.page_view_panel._START_UPDATE_BUTTON_XPATH))
        modal.wait_until_login_modal_appear.assert_called_once()
        modal.confirm.assert_called_once()

    @patch('taf.ul.oam.selenium_coam.pages.software.AbortSoftwareDownloadModal')
    def test_cancel_software_update(self, mock_modal):
        self.page_view_panel.click_enabled_element_after_visible = mock.Mock()
        modal = mock_modal.return_value
        modal.wait_until_abort_software_download_modal_appear = mock.Mock()
        modal.abort = mock.Mock()

        self.page_view_panel.cancel_software_update()
        self.page_view_panel.click_enabled_element_after_visible.\
            assert_called_once_with((By.XPATH, self.page_view_panel._CANCEL_UPDATE_BUTTON_XPATH))
        modal.wait_until_abort_software_download_modal_appear.assert_called_once()
        modal.abort.assert_called_once()

    def test_check_software_update_progress(self):
        context_element_text = 'success'
        percentage_element_text = '100%'
        expect_return_dict = {'status': context_element_text, 'percentage': percentage_element_text}

        def side_effect(input_xpath):
            return context_element_text \
                if input_xpath == self.page_view_panel._UPDATE_PROGRESS_CONTEXT_XPATH else percentage_element_text

        self.page_view_panel.get_text_by_xpath = mock.Mock(side_effect=side_effect)

        output = self.page_view_panel.check_software_update_progress()
        self.page_view_panel.get_text_by_xpath.assert_has_calls(
            [call.get_text_by_xpath(self.page_view_panel._UPDATE_PROGRESS_CONTEXT_XPATH),
             call.get_text_by_xpath(self.page_view_panel._UPDATE_PROGRESS_BAR_XPATH)])
        self.assertEqual(output, expect_return_dict)

    def test_get_all_current_software_version(self):
        return_dict = {'a': "1.0.0", 'b': '2.0.0'}
        self.page_view_panel.get_dict_from_elements_by_xpath = mock.Mock(return_value=return_dict)

        output = self.page_view_panel.get_all_current_software_version()
        self.page_view_panel.get_dict_from_elements_by_xpath.\
            assert_called_once_with(self.page_view_panel._VERSION_KEYS_XPATH,
                                    self.page_view_panel._VERSION_VALUES_XPATH, ':')
        self.assertEqual(output, return_dict)

    @patch('taf.ul.oam.selenium_coam.pages.software.RollbackSoftwareModal')
    def test_software_rollback(self, mock_modal):
        modal = mock_modal.return_value
        modal.wait_until_rollback_software_modal_appear = mock.Mock()
        modal.rollback = mock.Mock()
        self.page_view_panel.click_enabled_element_after_visible = mock.Mock()

        self.page_view_panel.software_rollback()
        self.page_view_panel.click_enabled_element_after_visible.\
            assert_called_once_with((By.XPATH, self.page_view_panel._ROLLBACK_BUTTON_XPATH))
        modal.wait_until_rollback_software_modal_appear.assert_called_once()
        modal.rollback.assert_called_once()

    def test__download_files_by_xpath(self):
        xpath = "//xpath"
        download_timeout = 1
        expect_dir = "/dir"
        self.page_view_panel.click_enabled_element_after_visible = mock.Mock()
        self.page_view_panel.download_files = mock.Mock(return_value=expect_dir)

        output = self.page_view_panel._download_files_by_xpath(xpath, download_timeout)
        self.page_view_panel.click_enabled_element_after_visible.assert_called_once_with((By.XPATH, xpath))
        self.page_view_panel.download_files.assert_called_once()
        self.assertEqual(output, expect_dir)

    def test_save_sw_update_report(self):
        download_timeout = 1
        expect_dir = "/dir"
        self.page_view_panel._download_files_by_xpath = mock.Mock(return_value=expect_dir)

        output = self.page_view_panel.save_sw_update_report(download_timeout)
        self.page_view_panel._download_files_by_xpath.\
            assert_called_once_with(self.page_view_panel._SAVE_SW_UPDATE_REPORT_BUTTON_XPATH, download_timeout)
        self.assertEqual(output, expect_dir)

    def test_backup_bts_site_configuration(self):
        download_timeout = 1
        expect_dir = "/dir"
        self.page_view_panel._download_files_by_xpath = mock.Mock(return_value=expect_dir)

        output = self.page_view_panel.backup_bts_site_configuration(download_timeout)
        self.page_view_panel._download_files_by_xpath.\
            assert_called_once_with(self.page_view_panel._BACKUP_CONFIGURATION_BUTTON, download_timeout)
        self.assertEqual(output, expect_dir)
